<script setup lang="ts">
import {knowledgeAvailable} from '../services/clientCapabilities'
import {computed,nextTick,ref} from 'vue'
import {aiLocalScope} from '../services/aiClientConfig'
let openedScope=''
function checkScope(){if(openedScope!==aiLocalScope())throw Error('本地空间已切换，请重新打开引用选择器')}
import {Close,Search} from '@element-plus/icons-vue'
import type {LearningReference} from '@note-flow/core/ai-learning'
import {listLearningReferences,resolveLearningReference,type ReferenceChoice} from '../services/learningReferences'
const props=defineProps<{selected:LearningReference[]}>(),emit=defineEmits<{change:[value:LearningReference[]]}>()
const dialog=ref<HTMLDialogElement>(),query=ref(''),tab=ref('all'),items=ref<ReferenceChoice[]>([]),chosen=ref<LearningReference[]>([]),busy=ref(false),error=ref(''),warnings=ref<string[]>([]),preview=ref<LearningReference|null>(null)
const filtered=computed(()=>items.value.filter(value=>(tab.value==='all'||value.kind===tab.value)&&value.title.toLocaleLowerCase().includes(query.value.toLocaleLowerCase())))
const count=computed(()=>chosen.value.reduce((sum,value)=>sum+value.content.length,0))
const label=(kind:string)=>kind==='note'?'笔记':kind==='knowledge'?'知识':kind==='task'?'任务':'附件'
async function open(){openedScope=aiLocalScope();chosen.value=[...props.selected];query.value='';tab.value='all';error.value='';preview.value=null;dialog.value?.showModal();busy.value=true;try{const result=await listLearningReferences();checkScope();items.value=result.items;warnings.value=result.warnings}catch{error.value='本机资料读取失败，请稍后重试'}finally{busy.value=false;await nextTick()}}
async function toggle(value:ReferenceChoice){const index=chosen.value.findIndex(item=>item.kind===value.kind&&item.uid===value.uid);if(index>=0){chosen.value.splice(index,1);return}if(chosen.value.length>=10){error.value='最多选择 10 项资料';return}busy.value=true;error.value='';try{const reference=await resolveLearningReference(value);checkScope();if(count.value+reference.content.length>20000)throw Error('所选资料超过 20000 字，请减少引用，为问题和历史讨论预留空间');chosen.value.push(reference);preview.value=reference}catch(source){error.value=source instanceof Error?source.message:'资料读取失败'}finally{busy.value=false}}
function commit(){try{checkScope();emit('change',[...chosen.value]);dialog.value?.close()}catch(source){error.value=(source as Error).message}}
defineExpose({open})
</script>
<template><dialog ref="dialog" class="reference-picker" aria-labelledby="reference-picker-title"><header><div><h3 id="reference-picker-title">添加引用</h3><small>选择本机资料，发送前可查看实际文字</small></div><button aria-label="关闭引用选择" @click="dialog?.close()"><Close/></button></header><label class="reference-search"><Search/><input v-model="query" :placeholder="knowledgeAvailable?'搜索笔记、知识、任务和附件':'搜索笔记、任务和附件'" aria-label="搜索引用资料"/></label><nav><button v-for="entry in [['all','全部'],['note','笔记'],['knowledge','知识'],['task','任务'],['attachment','附件']].filter(item=>knowledgeAvailable||item[0]!=='knowledge')" :key="entry[0]" :class="{active:tab===entry[0]}" @click="tab=entry[0]">{{entry[1]}}</button></nav><p v-if="error" role="alert">{{error}}</p><p v-for="warning in warnings" :key="warning" class="hint">{{warning}}</p><div class="reference-body"><section class="reference-list"><p v-if="busy" class="hint">正在读取本机资料…</p><p v-else-if="!filtered.length" class="hint">{{knowledgeAvailable?'没有找到本机资料。知识需先在当前账号打开，云端附件需先下载。':'没有找到本机资料。请检查笔记、任务或附件是否已保存在本机。'}}</p><button v-for="value in filtered" :key="value.kind+value.uid" class="reference-row" :disabled="busy||Boolean(value.reason)" :aria-pressed="chosen.some(item=>item.kind===value.kind&&item.uid===value.uid)" @click="toggle(value)"><span class="check">{{chosen.some(item=>item.kind===value.kind&&item.uid===value.uid)?'✓':'＋'}}</span><span><b>{{value.title}}</b><small>{{label(value.kind)}} · {{value.reason||'选择并查看文字'}}</small></span></button></section><section class="reference-preview"><template v-if="preview"><h4>{{preview.title}}</h4><small>{{preview.content.length}} 字 · 将发送的文字快照</small><pre>{{preview.content}}</pre></template><p v-else class="hint">选中资料后，在这里预览内容。</p></section></div><footer><span>已选 {{chosen.length}} 项 · {{count}} / 20000 字</span><button @click="dialog?.close()">取消</button><button class="primary" :disabled="busy" @click="commit">确认引用</button></footer></dialog></template>
<style scoped>
.reference-picker{width:min(850px,calc(100vw - 32px));max-height:85dvh;box-sizing:border-box;border:1px solid var(--pc-border,#e1e9e5);border-radius:16px;padding:22px;background:var(--pc-surface,#fff);color:var(--pc-text,#233d31);box-shadow:0 20px 70px #12332522}.reference-picker::backdrop{background:#102a2338}header{display:flex;justify-content:space-between;gap:12px;align-items:center}h3{margin:0;font-size:18px}small,.hint{font-size:12px;color:var(--pc-muted,#87979e)}button{font:inherit;cursor:pointer;border:1px solid var(--pc-border,#e1e9e5);border-radius:8px;padding:8px 12px;background:transparent;color:inherit}button:disabled{opacity:.5;cursor:default}header button{border:0;padding:5px}svg{width:18px;height:18px}.reference-search{display:flex;align-items:center;gap:8px;border:1px solid var(--pc-border,#e1e9e5);border-radius:10px;padding:10px;margin-top:18px}.reference-search input{border:0;outline:none;width:100%;font:inherit;color:inherit;background:transparent}nav{display:flex;gap:6px;margin:14px 0}nav button{border:0;font-size:13px}nav button.active{background:#edf5f0;color:var(--pc-primary,#176954)}.reference-body{display:grid;grid-template-columns:1fr 1fr;gap:16px;min-height:180px;height:min(45dvh,420px)}.reference-list,.reference-preview{min-width:0;overflow:auto}.reference-row{display:flex;align-items:flex-start;gap:10px;text-align:left;width:100%;border:0;padding:12px}.reference-row[aria-pressed=true]{background:#edf5f0}.reference-row b{display:block;font-size:13px;font-weight:500;overflow-wrap:anywhere}.reference-row small{display:block;margin-top:4px}.check{color:var(--pc-primary,#176954)}.reference-preview{background:var(--pc-bg,#f7faf8);border-radius:10px;padding:14px}.reference-preview h4{margin:0 0 5px;font-size:13px}.reference-preview pre{white-space:pre-wrap;overflow-wrap:anywhere;font-family:inherit;font-size:12px;line-height:1.8}.reference-picker [role=alert]{font-size:12px;color:#b04f43}footer{display:flex;justify-content:flex-end;align-items:center;gap:8px;padding-top:16px}footer span{margin-right:auto;font-size:12px;color:var(--pc-muted,#87979e)}.primary{background:var(--pc-primary,#176954);color:#fff;border:0}@media(max-width:600px){.reference-body{grid-template-columns:1fr;grid-template-rows:1fr 1fr;height:48dvh}.reference-picker{padding:16px}footer{flex-wrap:wrap}}
</style>
